#!/usr/bin/env python3
"""Record current native check results after every source/layout/export change."""
import datetime, hashlib, json, unittest, importlib.util
from pathlib import Path
from validate_drc import classify
R=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('mc1_tests',R/'test_design.py');mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
suite=unittest.defaultTestLoader.loadTestsFromModule(mod);result=unittest.TextTestRunner(verbosity=1).run(suite)
if not result.wasSuccessful():raise SystemExit('Regression checks failed')
drc=json.loads((R/'checks/drc.json').read_text());erc=json.loads((R/'checks/erc.json').read_text());design=json.loads((R/'design.json').read_text())
classification=classify(drc,(R/'mc1.kicad_pcb').read_text())
if classification['errors']:raise SystemExit(classification['errors'])
checks=dict(erc_violations=sum(len(s['violations']) for s in erc['sheets']),drc_violations=len(drc['violations']),unconnected_items=len(drc['unconnected_items']),schematic_parity_issues=len(drc['schematic_parity']),unit_tests_passed=result.testsRun)
checks.update(classified_mechanical_overlaps=classification['classified_mechanical_overlaps'],unclassified_violations=classification['unclassified_violations'])
if any(checks[k] for k in ['erc_violations','unconnected_items','schematic_parity_issues','unclassified_violations']):raise SystemExit('Native checks have outstanding issues')
v=dict(revision='MC1-Nano',layout_revision=design['layout_revision'],status='engineering_prototype_not_fabrication_release',checked_at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),kicad_version=drc.get('kicad_version'),board=design['board'],checks=checks,assembly=dict(fitted_through_hole_references=16,footprint_positions=18,unpopulated_service_pads=2,mounted_ready_modules=4,harness_or_service_headers=7,loose_axial_diodes=3,loose_axial_resistors=2,female_sockets=0,carrier_smt_components=0),physical_z_qualified=False,mechanics=design['mechanics'],rj45=design['mechanics']['rj45'],limitations=['Carrier assembled hardware untested; no fabrication authorization implied','Exact factory male pin fit and installed-board revision must be physically checked','Retained USB shells, underside components, rail lips and actual solder fillets require clearance checks','RJ45 plug boot, latch, bend radius and enclosure wall clearance require a physical check; reserved service rectangle is an engineering allowance','Power headroom, thermal behavior and I/O backpower isolation require bench verification','External PoE splitter, 3.3V buck, WK2132 and peripheral harnesses are separate finished modules','Antenna keepouts are geometric engineering provisions, not RF certification','Generic module schematic terminals do not validate internal regulator or IC electrical behavior','New WK2132 firmware path and radio coexistence require integration validation','H2 R7 removal is required before assembly; exact purchased revision and open-circuit isolation must be verified','USB connectors remain physically present, but postassembly cable insertion is intentionally not supported'])
v['sha256']={name:hashlib.sha256((R/name).read_bytes()).hexdigest() for name in ['mc1.kicad_pcb','mc1.kicad_pro','mc1.kicad_sch','design.json','routing/mc1.ses','manual-route.json','assembly-top.svg','assembly-bottom.svg','validate_drc.py','checks/drc.json','checks/drc-classification.json','board-top.svg','board-bottom.svg','schematic.svg','schematic.pdf','nano-pin-plan.json','h2-uart-isolation.svg','routing-metrics.json','measure_routing.py']}
(R/'verification.json').write_text(json.dumps(v,indent=2)+'\n');print('Native checks and evidence hashes recorded')
